 @GameTest(template="empty",timeoutTicks=1800)
 public static void naturalGuardAssignment(GameTestHelper t){floor(t);var job=place(t,3,3,Military.TABLE.get());var v=EntityType.VILLAGER.create(t.getLevel());var p=t.absolutePos(new BlockPos(4,2,3));v.moveTo(p.getX()+.5,p.getY(),p.getZ()+.5,0,0);t.getLevel().addFreshEntity(v);t.succeedWhen(()->{t.assertTrue(Military.guard(v)&&v.getData(Military.ARCHETYPE)>=0,"Native guard assignment/archetype");t.assertTrue(v.getOffers().isEmpty(),"Fake guard trades");t.assertTrue(v.getMaxHealth()==30,"Guard health balance");var loaded=EntityType.VILLAGER.create(t.getLevel());loaded.load(v.saveWithoutId(new CompoundTag()));t.assertTrue(loaded.getData(Military.ARCHETYPE).equals(v.getData(Military.ARCHETYPE)),"Archetype rerolled on NBT load");t.assertTrue(v.getMainHandItem().isEmpty()&&v.getOffhandItem().isEmpty(),"Role gear materialized as farm loot");System.out.println("MILITARY_ASSIGN_PASS nativeJob=true stableArchetype=true hp=30 noFakeTrade=true renderOwnedGear=true");});}
 @GameTest(template="empty",batch="guard_loss",timeoutTicks=1700)
 public static void tableLossGrace(GameTestHelper t){floor(t);var job=place(t,3,3,Military.TABLE.get());var v=worker(t,4,3,"druzhinnik",job);v.setVillagerXp(0);t.runAfterDelay(100,()->{t.getLevel().getPoiManager().getInRange(h->h.is(VillageRoles.JOBS.get("druzhinnik").getKey()),job,64,net.minecraft.world.entity.ai.village.poi.PoiManager.Occupancy.ANY).map(x->x.getPos()).toList().forEach(x->t.getLevel().destroyBlock(x,false));v.getBrain().eraseMemory(MemoryModuleType.JOB_SITE);});t.runAfterDelay(400,()->t.assertTrue(Military.guard(v),"Grace period lost"));t.runAfterDelay(1500,()->{t.assertTrue(v.getVillagerData().getProfession()==VillagerProfession.NONE,"Guard did not demote after grace");t.assertTrue(v.getMaxHealth()==20&&v.getMainHandItem().isEmpty(),"Role protection/gear not removed");System.out.println("MILITARY_TABLE_LOSS_PASS grace=true demotion=true roleModifiersRemoved=true noGear=true");t.succeed();});}
 @GameTest(template="empty",timeoutTicks=900)
 public static void actualGuardCombat(GameTestHelper t){floor(t);var job=place(t,3,3,Military.TABLE.get());var v=worker(t,4,3,"druzhinnik",job);v.setData(Military.ARCHETYPE,1);var z=EntityType.ZOMBIE.create(t.getLevel());var p=t.absolutePos(new BlockPos(5,2,3));z.moveTo(p.getX()+.5,p.getY(),p.getZ()+.5,0,0);z.setNoAi(true);t.getLevel().addFreshEntity(z);t.succeedWhen(()->{t.assertTrue(!z.isAlive(),"Actual guard did not defeat zombie");t.assertTrue(v.getHealth()>0&&v.getMaxHealth()==30,"Guard died/balance");System.out.println("MILITARY_COMBAT_PASS actualNativeBrain=true realZombieKilled=true");});}
 @GameTest(template="empty",timeoutTicks=100)
 public static void targetsAndFriendlyFire(GameTestHelper t){floor(t);var job=place(t,3,3,Military.TABLE.get());var v=worker(t,4,3,"druzhinnik",job);var citizen=EntityType.VILLAGER.create(t.getLevel());var golem=EntityType.IRON_GOLEM.create(t.getLevel());var creeper=EntityType.CREEPER.create(t.getLevel());t.assertTrue(!GuardBehavior.hostile(v,citizen)&&!GuardBehavior.hostile(v,golem)&&!GuardBehavior.hostile(v,creeper),"Friendly/creeper target");t.assertTrue(GuardBehavior.hostile(v,EntityType.SKELETON.create(t.getLevel()))&&GuardBehavior.hostile(v,ModEntities.BANDIT_FIGHTER.get().create(t.getLevel()))&&GuardBehavior.hostile(v,ModEntities.UPYR.get().create(t.getLevel())),"Hostile tags");float hp=citizen.getHealth();citizen.hurt(t.getLevel().damageSources().mobAttack(v),5);t.assertTrue(citizen.getHealth()==hp,"Friendly damage not excluded");System.out.println("MILITARY_TARGETS_PASS tags=true alliesSafe=true creeperSafe=true");t.succeed();}
 @GameTest(template="empty",timeoutTicks=700)
 public static void actualGolemBanditTarget(GameTestHelper t){floor(t);var g=EntityType.IRON_GOLEM.create(t.getLevel());var b=ModEntities.BANDIT_FIGHTER.get().create(t.getLevel());var p=t.absolutePos(new BlockPos(5,2,5));g.moveTo(p.getX(),p.getY(),p.getZ(),0,0);b.moveTo(p.getX()+2,p.getY(),p.getZ(),0,0);b.setNoAi(true);t.getLevel().addFreshEntity(g);t.getLevel().addFreshEntity(b);t.succeedWhen(()->{t.assertTrue(g.getTarget()==b||!b.isAlive(),"Golem did not acquire bandit");g.discard();b.discard();System.out.println("MILITARY_GOLEM_PASS realTargetSelection=true banditThreat=true");});}
 @GameTest(template="empty",timeoutTicks=100)
 public static void questAuthorityAndDoubleClaim(GameTestHelper t){floor(t);var pos=place(t,3,3,Military.TABLE.get());var p=new net.minecraft.server.level.ServerPlayer(t.getLevel().getServer(),t.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"quest-test"),net.minecraft.server.level.ClientInformation.createDefault());p.moveTo(pos.getX(),pos.getY(),pos.getZ(),0,0);var offer=MilitaryQuests.available(p,pos).stream().filter(q->q.getString("Type").equals("trophy")).findFirst().orElseThrow();String key=offer.getString("Key");t.assertTrue(MilitaryQuests.action(p,pos,key,0),"Accept");t.assertTrue(!MilitaryQuests.action(p,pos,key,2),"Reward without tokens");p.getInventory().add(new ItemStack(Military.TOKEN.get(),6));t.assertTrue(MilitaryQuests.action(p,pos,key,2),"Turn in tokens");int coins=p.getInventory().countItem(ModItems.ANCIENT_COIN.get());t.assertTrue(coins==6&&p.getInventory().countItem(Military.TOKEN.get())==0,"Consumption/reward");t.assertTrue(!MilitaryQuests.action(p,pos,key,2)&&p.getInventory().countItem(ModItems.ANCIENT_COIN.get())==coins,"Duplicate claim");var before=MilitaryQuests.available(p,pos).stream().map(q->q.getString("Key")+q.getList("Rewards",10)).toList();t.assertTrue(before.equals(MilitaryQuests.available(p,pos).stream().map(q->q.getString("Key")+q.getList("Rewards",10)).toList()),"Reopen reroll");var saved=MilitaryQuests.state(p).copy();p.setData(Military.QUESTS,saved);t.assertTrue(!MilitaryQuests.action(p,pos,key,2),"Attachment restore duplicate");p.discard();System.out.println("MILITARY_QUEST_PASS serverValidated=true tokensConsumed=6 rewardOnce=true reopenStable=true attachmentRoundtrip=true");t.succeed();}
 @GameTest(template="empty",batch="barracks_124",timeoutTicks=100)
 public static void barracksPhysicalPaths(GameTestHelper t){
  var origin=t.absolutePos(new BlockPos(1,1,1));var template=t.getLevel().getStructureManager().getOrCreate(VillageRoles.id("military/barracks"));t.assertTrue(template.getSize().equals(new Vec3i(20,21,20)),"Missing rebuilt barracks");
  template.placeInWorld(t.getLevel(),origin,origin,new StructurePlaceSettings().setKnownShape(true).addProcessor(JigsawReplacementProcessor.INSTANCE),t.getLevel().random,2);
  var v=EntityType.VILLAGER.create(t.getLevel());v.setNoAi(true);v.moveTo(origin.getX()+7.5,origin.getY()+3,origin.getZ()+3.5,0,0);((net.minecraft.world.entity.ai.navigation.GroundPathNavigation)v.getNavigation()).setCanOpenDoors(true);t.getLevel().addFreshEntity(v);
  t.runAfterDelay(20,()->{v.setOnGround(true);for(var offset:List.of(new BlockPos(10,3,7),new BlockPos(10,3,10))){var path=v.getNavigation().createPath(origin.offset(offset),0);t.assertTrue(path!=null&&path.canReach(),"Barracks tables inaccessible "+offset);}
   for(int y=3;y<=15;y++){var p=origin.offset(15,y,13);var state=t.getLevel().getBlockState(p);t.assertTrue(state.is(Blocks.LADDER)&&state.canSurvive(t.getLevel(),p),"Broken tower ladder "+p);}
   var chest=t.getLevel().getBlockEntity(origin.offset(11,3,15));t.assertTrue(chest instanceof net.minecraft.world.level.block.entity.ChestBlockEntity,"Supply chest absent");System.out.println("MILITARY_BARRACKS_PASS rebuilt=true twoTablesReachable=true supportedPlayerLadder=true supplyChest=true");v.discard();t.succeed();});
 }

 @GameTest(template="empty",timeoutTicks=100)
 public static void nativeVillageBarracksPlanning(GameTestHelper t){var l=t.getLevel();var structure=l.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).get(net.minecraft.resources.ResourceLocation.withDefaultNamespace("village_plains"));var generator=l.getChunkSource().getGenerator();int found=0,plans=0;for(int i=0;i<128;i++){var start=structure.generate(l.registryAccess(),generator,generator.getBiomeSource(),l.getChunkSource().randomState(),l.getStructureManager(),l.getSeed(),new net.minecraft.world.level.ChunkPos(2000+i*40,3000+i*31),0,l,b->true);if(!start.isValid())continue;plans++;long count=start.getPieces().stream().filter(p->p instanceof net.minecraft.world.level.levelgen.structure.PoolElementStructurePiece e&&e.getElement().toString().contains("slavicmyths:military/barracks")).count();t.assertTrue(count<=1,"Natural jigsaw assembly contains duplicate barracks");if(count==1&&++found>=3)break;}t.assertTrue(found>0,"Natural native village planning never selected barracks");System.out.println("MILITARY_NATURAL_PLANNING_PASS nativeVillagePlans="+plans+" barracksPlans="+found+" maxPerVillage=1 noChunkLoading=true");t.succeed();}
 @GameTest(template="empty",batch="raid",timeoutTicks=500)
 public static void actualBanditRaid(GameTestHelper t){var l=t.getLevel();BlockPos anchor=t.absolutePos(new BlockPos(5,2,5));for(int dx=-4;dx<=4;dx++)for(int dz=-4;dz<=4;dz++){l.setChunkForced((anchor.getX()>>4)+dx,(anchor.getZ()>>4)+dz,true);l.getChunk((anchor.getX()>>4)+dx,(anchor.getZ()>>4)+dz);}t.runAfterDelay(40,()->{var events=BanditRaids.get(l);t.assertTrue(events.start(l,anchor,UUID.randomUUID(),true),"Real raid failed to start outside settlement");var state=events.inspect(anchor);var ids=state.getList("Attackers",10);t.assertTrue(ids.size()>=3&&ids.size()<=5,"Small party size");t.assertTrue(!events.start(l,anchor,UUID.randomUUID(),true),"Duplicate raid started");for(Tag tag:ids){var b=(org.slavicmyths.bandit.BanditEntity)l.getEntity(((CompoundTag)tag).getUUID("Id"));t.assertTrue(b!=null&&b.getPersistentData().getBoolean("MilitaryRaider")&&b.blockPosition().distSqr(anchor)>40*40&&b.role!=org.slavicmyths.bandit.BanditEntity.ATAMAN,"Spawn/role/record invalid: entity="+b+" state="+(b==null?"missing":b.getPersistentData()+" distance="+b.blockPosition().distSqr(anchor)+" role="+b.role));}
  t.runAfterDelay(100,()->{var current=events.inspect(anchor).getList("Attackers",10);for(Tag tag:current){var b=(org.slavicmyths.bandit.BanditEntity)l.getEntity(((CompoundTag)tag).getUUID("Id"));t.assertTrue(b!=null,"Attacker vanished");b.hurt(l.damageSources().generic(),10000);}t.assertTrue(!events.inspect(anchor).getBoolean("Active")&&events.inspect(anchor).getString("EndReason").equals("VICTORY"),"Raid did not finish on actual deaths");t.assertTrue(events.inspect(anchor).getLong("Cooldown")>l.getGameTime(),"Post-raid cooldown lost");for(int dx=-4;dx<=4;dx++)for(int dz=-4;dz<=4;dz++)l.setChunkForced((anchor.getX()>>4)+dx,(anchor.getZ()>>4)+dz,false);System.out.println("MILITARY_RAID_PASS actualSpawnOutside=true smallParty=true duplicateStartBlocked=true realDeathEvents=true victory=true cooldown=true");t.succeed();});});}
 @GameTest(template="empty",timeoutTicks=100)
 public static void supplyLootStatistics(GameTestHelper t){var l=t.getLevel();var loot=l.getServer().reloadableRegistries().getLootTable(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.LOOT_TABLE,VillageRoles.id("chests/barracks_supply")));var params=new net.minecraft.world.level.storage.loot.LootParams.Builder(l).withParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.ORIGIN,t.absolutePos(BlockPos.ZERO).getCenter()).create(net.minecraft.world.level.storage.loot.parameters.LootContextParamSets.CHEST);int diamonds=0,saddles=0,food=0;for(int i=0;i<1000;i++)for(var item:loot.getRandomItems(params)){if(item.is(Items.DIAMOND)){t.assertTrue(item.getCount()==1,"Diamond stack");diamonds++;}if(item.is(Items.SADDLE))saddles++;if(item.is(Items.BREAD))food++;}t.assertTrue(diamonds<20&&saddles<80&&food>500,"Loot tiers unbalanced");System.out.println("MILITARY_LOOT_PASS samples=1000 diamonds="+diamonds+" saddles="+saddles+" bread="+food+" diamondCount=1");t.succeed();}

