 @GameTest(template="empty",batch="guard_night",timeoutTicks=1600)
 public static void nightRestAndThreat(GameTestHelper t){floor(t);var anchor=place(t,2,2,Military.TABLE.get());t.setBlock(new BlockPos(4,2,3),Blocks.RED_BED.defaultBlockState().setValue(net.minecraft.world.level.block.BedBlock.FACING,Direction.SOUTH).setValue(net.minecraft.world.level.block.BedBlock.PART,net.minecraft.world.level.block.state.properties.BedPart.FOOT));t.setBlock(new BlockPos(4,2,4),Blocks.RED_BED.defaultBlockState().setValue(net.minecraft.world.level.block.BedBlock.FACING,Direction.SOUTH).setValue(net.minecraft.world.level.block.BedBlock.PART,net.minecraft.world.level.block.state.properties.BedPart.HEAD));var v=worker(t,4,4,"druzhinnik",anchor);v.setData(Military.ARCHETYPE,1);v.getBrain().setMemory(MemoryModuleType.HOME,GlobalPos.of(t.getLevel().dimension(),t.absolutePos(new BlockPos(4,2,4))));t.getLevel().setDayTime(13000);v.getBrain().updateActivityFromSchedule(13000,t.getLevel().getGameTime()+40);final Zombie[] attacker={null};t.succeedWhen(()->{if(attacker[0]==null){t.assertTrue(v.isSleeping(),"Guard never rested at night");attacker[0]=EntityType.ZOMBIE.create(t.getLevel());attacker[0].moveTo(v.getX()+1,v.getY(),v.getZ()+1,0,0);attacker[0].setNoAi(true);t.getLevel().addFreshEntity(attacker[0]);v.hurt(t.getLevel().damageSources().mobAttack(attacker[0]),1);throw new GameTestAssertException("Wait for actual night combat");}t.assertTrue(!attacker[0].isAlive()&&v.isSleeping(),"Guard failed night defense or return to rest");t.getLevel().setDayTime(3000);v.discard();System.out.println("MILITARY_NIGHT_PASS actualSleep=true directThreatKilled=true resumedRest=true");});}

