 @GameTest(template="empty",batch="guard_boundary",timeoutTicks=500)
 public static void pursuitBoundary(GameTestHelper t){floor(t);var anchor=place(t,3,3,Military.TABLE.get());var v=worker(t,4,3,"druzhinnik",anchor);v.setData(Military.ARCHETYPE,1);var z=EntityType.ZOMBIE.create(t.getLevel());z.moveTo(v.getX()+5,v.getY(),v.getZ()+4,0,0);z.setNoAi(true);z.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.LEATHER_HELMET));t.getLevel().addFreshEntity(z);final boolean[] moved={false};t.succeedWhen(()->{if(!moved[0]){t.assertTrue(v.getPersistentData().hasUUID("GuardTarget"),"No actual threat acquired");z.moveTo(anchor.getX()+55,anchor.getY(),anchor.getZ(),0,0);moved[0]=true;throw new GameTestAssertException("Wait for bounded pursuit cleanup");}t.assertTrue(!v.getPersistentData().hasUUID("GuardTarget"),"Guard retained target outside 48 blocks");t.assertTrue(v.blockPosition().distSqr(anchor)<=32*32,"Guard exceeded patrol boundary");z.discard();v.discard();System.out.println("MILITARY_PURSUIT_PASS acquiredRealThreat=true targetReleasedBeyond48=true withinPatrol32=true");t.succeed();});}

