 public static void strongholdBanditAttacksResident(GameTestHelper t){floor(t);var v=EntityType.VILLAGER.create(t.getLevel());var b=ModEntities.BANDIT_FIGHTER.get().create(t.getLevel());var p=t.absolutePos(new BlockPos(4,2,4));v.moveTo(p.getX()+.5,p.getY(),p.getZ()+.5,0,0);v.setNoAi(true);b.moveTo(p.getX()+4.5,p.getY(),p.getZ()+.5,0,0);b.camp=UUID.randomUUID();b.campTotal=org.slavicmyths.bandit.StrongholdRecords.TOTAL;b.campMember=2;b.home=p;b.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.IRON_SWORD));t.getLevel().addFreshEntity(v);t.getLevel().addFreshEntity(b);t.succeedWhen(()->{t.assertTrue(v.getHealth()<v.getMaxHealth(),"Stronghold alarm gate blocked actual resident combat");b.discard();v.discard();System.out.println("MILITARY_STRONGHOLD_RESIDENT_PASS calmZone=true npcTargetNotAlarmBlocked=true realDamage=true");});}
 @GameTest(template="empty",batch="golem_real_combat",timeoutTicks=1200)
 public static void golemActuallyDefeatsBandit(GameTestHelper t){floor(t);var g=EntityType.IRON_GOLEM.create(t.getLevel());var b=ModEntities.BANDIT_FIGHTER.get().create(t.getLevel());var p=t.absolutePos(new BlockPos(2,2,5));g.moveTo(p.getX()+.5,p.getY(),p.getZ()+.5,0,0);b.moveTo(p.getX()+7.5,p.getY(),p.getZ()+.5,0,0);b.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.IRON_SWORD));t.getLevel().addFreshEntity(g);t.getLevel().addFreshEntity(b);t.succeedWhen(()->{t.assertTrue(!b.isAlive(),"Golem failed actual live bandit combat; target="+g.getTarget());t.assertTrue(g.isAlive(),"Bandit defeated golem");g.discard();System.out.println("MILITARY_GOLEM_COMBAT_PASS liveBandit=true actualMelee=true banditDefeated=true");});}

 @GameTest(template="empty",batch="bandit_archer_resident",timeoutTicks=1200)
 public static void banditArcherAttacksResident(GameTestHelper t){floor(t);var v=EntityType.VILLAGER.create(t.getLevel());var b=ModEntities.BANDIT_ARCHER.get().create(t.getLevel());var p=t.absolutePos(new BlockPos(1,2,2));v.moveTo(p.getX()+.5,p.getY(),p.getZ()+.5,0,0);v.setNoAi(true);var bp=t.absolutePos(new BlockPos(9,2,8));b.moveTo(bp.getX()+.5,bp.getY(),bp.getZ()+.5,0,0);b.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.BOW));t.getLevel().addFreshEntity(v);t.getLevel().addFreshEntity(b);t.succeedWhen(()->{t.assertTrue(v.getHealth()<v.getMaxHealth(),"Bandit archer never damaged resident with arrow");t.assertTrue(b.getTarget()==v||!v.isAlive(),"Archer selected a different target");b.discard();v.discard();System.out.println("MILITARY_BANDIT_ARCHER_PASS autonomousResidentTarget=true realArrowDamage=true");});}

